Param(    [Parameter(Mandatory=$true)] [string]$stackName,    [Parameter(Mandatory=$true)] [string]$containerVersion,    [Parameter(Mandatory=$true)] [string]$cmsVersionParam,    [Parameter(Mandatory=$true)] [string]$pluginsLayerVersion,    [Parameter(Mandatory=$true)] [string]$otherPlugins,    [Parameter(Mandatory=$true)] [string]$vpcSecurityGroupId,    [Parameter(Mandatory=$true)] [string]$vpcSubnet1Id,    [Parameter(Mandatory=$true)] [string]$vpcSubnet2Id,    [Parameter(Mandatory=$true)] [string]$certificateArn,    [Parameter(Mandatory=$true)] [string]$domain,    [Parameter(Mandatory=$true)] [string]$emailUsername,    [Parameter(Mandatory=$true)] [string]$emailPassword,    [Parameter(Mandatory=$true)] [string]$emailHost,    [Parameter(Mandatory=$true)] [string]$emailPort,    [Parameter(Mandatory=$true)] [string]$emailSsl,    [Parameter(Mandatory=$true)] [string]$connectionString,    [Parameter(Mandatory=$true)] [string]$uploadsAccessKey,    [Parameter(Mandatory=$true)] [string]$uploadsSecretKey,    [Parameter(Mandatory=$true)] [string]$regionName)$cmsVersionParam = $cmsVersionParam.Replace("v", "")$cmsVersion = $cmsVersionParam.Replace(".", "-")$containerVersion = $containerVersion.Replace("v", "").Replace("-", ".")$stackNameLower = $stackName.ToLower() echo "Creating the ${stackName} stack"aws --region "${regionName}" cloudformation deploy `--template-file "cloudformation.template" `--stack-name "${stackName}" `--s3-bucket "md-cms-awslambda-cloudformatio-core" `--capabilities "CAPABILITY_IAM" `--parameter-overrides `	Domain="${domain}" `	OmegaLambdaContainerCodeUriBucket="md-cms-awslambda-container" `	OmegaLambdaContainerCodeUriKey="container.awslambda.${containerVersion}" `	StackName="${stackNameLower}" `	BillingGroup="${stackNameLower}" `	VpcSecurityGroupId="${vpcSecurityGroupId}" `	VpcSubnet1Id="${vpcSubnet1Id}" `	VpcSubnet2Id="${vpcSubnet1Id}" `	CloudFrontCertificateArn="${certificateArn}" `	OmegaCmsDataAccessPlugins="[ \`"MD.Tools.BaseDataAccess.Plugins.WebService.Core\`", \`"MD.Tools.BaseDataAccess.Plugins.MySql.Core\`" ]" `	OmegaCmsDataAccessPluginSettings="{\`"MD.Tools.BaseDataAccess.Plugins.MySql.Core\`": \`"${connectionString}\`",\`"MD.Tools.BaseDataAccess.Plugins.WebService.Core\`": \`"\`"}" `	OmegaCmsCorsOrigins="[\`"https://${domain}\`"]" `	OmegaCmsSessionDomain="${domain}" `	OmegaCmsSessionTimeout="01:00:00" `	OmegaCmsDefaultLcid="2057" `	EmailUsername="${emailUsername}" `	EmailPassword="${emailPassword}" `	EmailHost="${emailHost}" `	EmailPort="${emailPort}" `	EmailUseSsl="${emailSsl}" `	AdminStageName="admin" `	AdminWebAppPath="/opt/MD.CMS.Administration.Core.AwsLambda/" `	AdminAppReferencePath="MD.CMS.Administration.Core.AwsLambda.dll.MD.CMS.Administration.Core.AwsLambda.AwsStartup" `	AdminGatewayName="${stackName}-OmegaCMS-Admin" `	AdminMDCMSBusinessLogicCoreDefaultLcid="2057" `	AdminMDCMSBusinessLogicCoreGoogleApiTranslationKey="" `	AdminMDCMSBusinessLogicCoreGoogleMapsJsKey="" `	AdminMDToolsHelpersCoreProviderOptions="" `	AdminMDToolsHelpersCoreDefaultFileProvider="1" `	AdminMDToolsHelpersCoreVerboseLoggingReflectionEnabled="" `	AdminMDCMSAdministrationCorePluginsDirectory="/opt/AwsLambdaPlugins/" `	AdminMDCMSAdministrationCorePluginsFileProviderType="1" `	AdminBasePluginsLayer="arn:aws:lambda:us-east-1:518606024901:layer:AwsLambdaPlugins:${pluginsLayerVersion}" `	AdminProductLayer="arn:aws:lambda:us-east-1:518606024901:layer:MD-CMS-Administration-Core-AwsLambda-v${cmsVersion}:1" `	AdminOtherPlugins="${otherPlugins}" `	WebApiStageName="ws" `	WebApiWebAppPath="/opt/MD.CMS.WebApi.Core.AwsLambda/" `	WebApiAppReferencePath="MD.CMS.WebApi.Core.AwsLambda.dll.MD.CMS.WebApi.Core.AwsLambda.AwsStartup" `	WebApiGatewayName="${stackName}-OmegaCMS-WebApi" `	WebApiMDCMSBusinessLogicCoreRootAdminAccount="" `	WebApiMDCMSWebApiCorePluginsDirectory="/opt/AwsLambdaPlugins/" `	WebApiMDCMSWebApiCorePluginsFileProviderType="1" `	WebApiMDToolsBaseDataAccessPluginsCoreDataAccessPlugins="" `	WebApiMDToolsBaseDataAccessPluginsCoreDataAccessPluginSettings="" `	WebApiMDToolsBaseDataAccessPluginsCoreBaseDataAccessPluginsDirectory="/opt/AwsLambdaPlugins/" `	WebApiMDToolsBaseDataAccessPluginsCoreBaseDataAccessPluginsFileProviderType="1" `	WebApiMDToolsHelpersCoreProviderOptions="'{ \`"AWSS3FileProvider\`": \`"   {\\\`"BucketName\\\`": \\\`"${stackNameLower}-admin-uploads\\\`", \\\`"AccessKey\\\`": \\\`"${uploadsAccessKey}\\\`", \\\`"SecretKey\\\`": \\\`"${uploadsSecretKey}\\\`", \\\`"RegionDisplayName\\\`": \\\`"${regionName}\\\`", \\\`"CacheFiles\\\`": false, \\\`"CacheLocation\\\`": \\\`"\\\`"}   \`" }'" `	WebApiMDToolsHelpersCoreDefaultFileProvider="1" `	WebApiMDCMSWebApiCoreBaseApiPath="" `	WebApiMDCMSWebApiCoreBaseFolder="" `	WebApiApiTimeout="30" `	WebApiTraceLevel="1" `	WebApiMDToolsHelpersCoreVerboseLoggingReflectionEnabled="" `	WebApiBasePluginsLayer="arn:aws:lambda:us-east-1:518606024901:layer:AwsLambdaPlugins:${pluginsLayerVersion}" `	WebApiProductLayer="arn:aws:lambda:us-east-1:518606024901:layer:MD-CMS-WebApi-Core-AwsLambda-v${cmsVersion}:1" ` `	WebApiOtherPlugins="${otherPlugins}" ` `	WebApiSocketsOtherPlugins="${otherPlugins}" `	WebApiSocketsBasePluginsLayer="arn:aws:lambda:us-east-1:518606024901:layer:AwsLambdaPlugins:${pluginsLayerVersion}" `	WebApiSocketsProductLayer="arn:aws:lambda:us-east-1:518606024901:layer:MD-CMS-WebApi-Sockets-Core-AwsLambda-v${cmsVersion}:1" `	WebApiSocketsStageName="ws-web-sockets" `	WebApiSocketsWebAppPath="/opt/MD.CMS.WebApi.Sockets.Core.AwsLambda/" `	WebApiSocketsAppReferencePath="MD.CMS.WebApi.Sockets.Core.AwsLambda.dll.MD.CMS.WebApi.Sockets.Core.AwsLambda.Functions" `	WebApiSocketsGatewayName="${stackName}-OmegaCMS-WebApi-Sockets" `	WebApiSocketsMDCMSBusinessLogicCoreRootAdminAccount="" `	WebApiSocketsMDCMSWebApiCorePluginsDirectory="/opt/AwsLambdaPlugins/" `	WebApiSocketsMDCMSWebApiCorePluginsFileProviderType="1" `	WebApiSocketsMDToolsBaseDataAccessPluginsCoreDataAccessPlugins="" `	WebApiSocketsMDToolsBaseDataAccessPluginsCoreDataAccessPluginSettings="" `	WebApiSocketsMDToolsBaseDataAccessPluginsCoreBaseDataAccessPluginsDirectory="/opt/AwsLambdaPlugins/" `	WebApiSocketsMDToolsBaseDataAccessPluginsCoreBaseDataAccessPluginsFileProviderType="1" `	WebApiSocketsMDToolsHelpersCoreProviderOptions="" `	WebApiSocketsMDToolsHelpersCoreDefaultFileProvider="1" `	WebApiSocketsMDCMSWebApiCoreBaseApiPath="" `	WebApiSocketsApiTimeout="30" `	WebApiSocketsTraceLevel="1" `	WebApiSocketsMDToolsHelpersCoreVerboseLoggingReflectionEnabled="false" `	WebApiSocketsDebugMode="false"echo "${stackName} stack created!"echo "Transferring static assets for the ${stackName} stack"aws s3 cp "s3://omega-cms-admin/assets/assets.${cmsVersionParam}" "s3://${stackNameLower}-admin-assets" --exclude "js/ext/*" --exclude "js/gridstack/*" --exclude "scripts/businessLogic*" --exclude "scripts/app/*.js" --exclude "scripts/app/*.scss" --exclude "scripts/.scannerwork/*" --exclude "scripts/plugins/tinymce-dist/node_modules/*" --recursive --quietaws s3api put-object --bucket "${stackNameLower}-admin-uploads" --key "uploads/"echo "${stackName} static assets transferred!"